package com.example.onlineshop.catalog.api;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.example.onlineshop.catalog.application.CatalogProductRepository; import com.example.onlineshop.catalog.domain.*; import com.fasterxml.jackson.databind.*; import java.nio.file.*; import java.time.Instant; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.junit.jupiter.Container; import org.testcontainers.junit.jupiter.Testcontainers; import org.testcontainers.postgresql.PostgreSQLContainer;
@Testcontainers(disabledWithoutDocker=false) @SpringBootTest @AutoConfigureMockMvc class CatalogApiTest {
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:16.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @Autowired CatalogProductRepository repository;
 @Test void createListDetailAndProblems() throws Exception {var body="{\"name\":\"Synthetic Tea\",\"description\":\"Fixture\",\"price\":\"12.30\",\"currency\":\"NZD\",\"stockQuantity\":4}";var json=mvc.perform(post("/api/v1/products").contentType("application/json").content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.price").value("12.30")).andReturn().getResponse().getContentAsString();var id=json.replaceAll(".*\\\"id\\\":\\\"([^\\\"]+).*","$1");mvc.perform(get("/api/v1/products/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id));mvc.perform(get("/api/v1/products")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));Assertions.assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM products",Integer.class));Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_sku WHERE product_id=? AND is_default",Integer.class,UUID.fromString(id)));var actor=UUID.randomUUID();var now=Instant.parse("2026-10-24T00:00:00Z");var attribute=new ProductAttribute(UUID.randomUUID(),"origin","Origin",AttributeDataType.TEXT,AttributeScope.PRODUCT,false,LifecycleStatus.ACTIVE);attribute.addValue(UUID.randomUUID(),"nz","New Zealand");repository.save(attribute,actor,now);repository.save(new Category(UUID.randomUUID(),"tea","Tea",null,LifecycleStatus.ACTIVE,0,0),actor,now);repository.save(new ProductImage(UUID.randomUUID(),UUID.fromString(id),null,"/tea.png","Tea",0,true,0),actor,now);Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_attribute_value",Integer.class));Assertions.assertEquals(actor,jdbc.queryForObject("SELECT created_by FROM category",UUID.class));Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_image",Integer.class));mvc.perform(post("/api/v1/products").contentType("application/json").content("{}" )).andExpect(status().isUnprocessableEntity()).andExpect(content().contentType("application/problem+json"));mvc.perform(get("/api/v1/products/00000000-0000-0000-0000-000000000000")).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("PRODUCT_NOT_FOUND"));}
 @Test void malformedIs400() throws Exception {mvc.perform(post("/api/v1/products").contentType("application/json").content("{" )).andExpect(status().isBadRequest());}
 @Test void frameworkErrorsUseProblemDetails() throws Exception {mvc.perform(put("/api/v1/products").contentType("application/json").content("{}" )).andExpect(status().isMethodNotAllowed()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("METHOD_NOT_ALLOWED"));mvc.perform(post("/api/v1/products").contentType("application/xml").content("<product/>" )).andExpect(status().isUnsupportedMediaType()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("UNSUPPORTED_MEDIA_TYPE"));mvc.perform(get("/api/v1/products/x/y")).andExpect(status().isNotFound()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("RESOURCE_NOT_FOUND"));}
 @Test void publishesApprovedOpenApiResponses() throws Exception {mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['201']").exists()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['400'].content['application/problem+json']").exists()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['422'].content['application/problem+json']").exists()).andExpect(jsonPath("$.paths['/api/v1/products/{productId}'].get.responses['404'].content['application/problem+json']").exists());}
 @Test void checkedOpenApiPathsAndResponsesMatchRuntime() throws Exception {var mapper=new ObjectMapper();JsonNode runtime=mapper.readTree(mvc.perform(get("/v3/api-docs")).andReturn().getResponse().getContentAsString());JsonNode checked=mapper.readTree(Paths.get("../../tests/contracts/catalog-api.json").toFile());Assertions.assertEquals(fieldNames(checked.path("paths")),fieldNames(runtime.path("paths")));Assertions.assertEquals(fieldNames(checked.path("components").path("schemas")),fieldNames(runtime.path("components").path("schemas")));for(String path:fieldNames(checked.path("paths"))){for(String method:fieldNames(checked.path("paths").path(path))){Assertions.assertEquals(fieldNames(checked.path("paths").path(path).path(method).path("responses")),fieldNames(runtime.path("paths").path(path).path(method).path("responses")),path+" "+method);}}}
 private static Set<String> fieldNames(JsonNode node){var names=new TreeSet<String>();node.fieldNames().forEachRemaining(names::add);return names;}
}
